"use client";

import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { BlockFrame } from "../parts/block-frame";
import {
  ACCOUNT,
  HEALTH_RANGES,
  type HealthRange,
  readSignal,
  RISK_SUMMARIES,
  SCORE,
  scoreChange,
  scoreStatus,
  SIGNALS,
  TERM,
} from "./account-health/data";
import { NextStep } from "./account-health/next-step";
import { RenewalTerm } from "./account-health/renewal-term";
import { RiskSummary } from "./account-health/risk-summary";
import { ScoreLead } from "./account-health/score-lead";
import { SignalRow } from "./account-health/signal-row";

/**
 * A customer account at a glance: its health score first, then the renewal,
 * the five signals behind the score, a short generated summary and the one
 * step to take next. Nothing runs by itself, and the score never counts up.
 */
export function AccountHealth({ className }: { className?: string }) {
  const [range, setRange] = useState<HealthRange>("30");
  const titleId = useId();

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 px-5 pt-4">
        <div className="min-w-0">
          <h2 id={titleId} className="truncate text-sm font-medium">
            {ACCOUNT.name}
          </h2>
          <p className="truncate text-sm text-muted-foreground">{ACCOUNT.plan}</p>
        </div>
        <SegmentedControl aria-label="Trend period" options={HEALTH_RANGES} value={range} onValueChange={setRange} />
      </header>

      <div className="flex flex-wrap items-end gap-x-10 gap-y-5 px-5 pt-6 pb-5">
        <ScoreLead score={SCORE} status={scoreStatus(SCORE)} change={scoreChange(range)} changeNote={`in ${range} days`} />
        <RenewalTerm
          renews={TERM.renews}
          totalDays={TERM.totalDays}
          daysUsed={TERM.daysUsed}
          daysLeft={TERM.daysLeft}
          className="min-w-56 flex-1 pb-1.5"
        />
      </div>

      <ul aria-label="Signals behind the score" className="border-y border-border py-2">
        {SIGNALS.map((signal) => {
          const reading = readSignal(signal, range);
          return <SignalRow key={signal.id} signal={signal} days={reading.days} value={reading.value} change={reading.change} />;
        })}
      </ul>

      <div className="grid @2xl:grid-cols-2">
        <RiskSummary versions={RISK_SUMMARIES} className="p-5" />
        <NextStep
          action={`Call ${ACCOUNT.contact} by Nov 14 about staff sign-ins`}
          className="border-t border-border p-5 @2xl:border-t-0 @2xl:border-l"
        />
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { BellIcon, CalendarIcon, GlobeIcon, MessageIcon, UsersIcon } from "@/components/blocks/parts/icons";

import { formatDay, formatOnePlace, formatWhole, SAMPLE_END } from "../../lib/format";
import { makeSeries, mean, percentChange, sum } from "../../lib/plot";
import type { Status } from "../../lib/status";

/** How many days the trends look back. */
export type HealthRange = "30" | "90";

/** One thing the health score watches. */
export interface HealthSignal {
  id: string;
  /** At most three words, so the row stays on one line. */
  label: string;
  icon: typeof CalendarIcon;
  /** The last 90 daily readings. */
  days: number[];
  lowerIsBetter: boolean;
  status: Status;
  /** Writes the headline value from the newest seven days. */
  read: (week: number[]) => string;
}

/** The range choices, in the order the control shows them. */
export const HEALTH_RANGES: { value: HealthRange; label: string }[] = [
  { value: "30", label: "30 days" },
  { value: "90", label: "90 days" },
];

const DAY_MS = 86_400_000;
const TERM_START = Date.UTC(2025, 11, 12);
const TERM_END = Date.UTC(2026, 11, 12);

/** The account on the card. Every name here is invented. */
export const ACCOUNT = {
  name: "Calder and Wren Physiotherapy",
  plan: "Group plan, 5 clinics",
  contact: "Tomas Lindqvist",
};

/** The contract term, measured against the last sample day so it reads the same on every render. */
export const TERM = {
  renews: formatDay(new Date(TERM_END)),
  totalDays: Math.round((TERM_END - TERM_START) / DAY_MS),
  daysUsed: Math.round((SAMPLE_END - TERM_START) / DAY_MS),
  daysLeft: Math.round((TERM_END - SAMPLE_END) / DAY_MS),
};

/** The score on each of the last 90 days: a steady slide from 67 to 58. */
export const SCORE_DAYS = Array.from({ length: 90 }, (_, day) => Math.round(67 - 9 * (day / 89) ** 1.5));

/** The score today, out of 100. */
export const SCORE = SCORE_DAYS[SCORE_DAYS.length - 1] ?? 0;

/** The state a score falls in: under 40 is at risk, 40 to 69 is watch, 70 and over is good. */
export function scoreStatus(score: number): Status {
  if (score >= 70) return "good";
  return score >= 40 ? "watch" : "bad";
}

/** How many points the score moved across the range. */
export function scoreChange(range: HealthRange): number {
  return SCORE - (SCORE_DAYS[SCORE_DAYS.length - Number(range)] ?? SCORE);
}

const whole = (seed: number, start: number, end: number, noise: number) => makeSeries(seed, 90, start, end, noise).map(Math.round);
const percent = (seed: number, start: number, end: number, noise: number) =>
  makeSeries(seed, 90, start, end, noise).map((value) => Math.min(100, value));

/** The five signals, weakest first. */
export const SIGNALS: HealthSignal[] = [
  {
    id: "bookings",
    label: "Bookings made",
    icon: CalendarIcon,
    days: whole(401, 78, 58, 12),
    lowerIsBetter: false,
    status: "bad",
    read: (week) => `${formatWhole(sum(week))} a week`,
  },
  {
    id: "staff",
    label: "Staff signing in",
    icon: UsersIcon,
    days: whole(409, 19, 14, 3),
    lowerIsBetter: false,
    status: "watch",
    read: (week) => `${formatWhole(mean(week))} a day`,
  },
  {
    id: "support",
    label: "Support requests",
    icon: MessageIcon,
    days: whole(419, 2, 6, 1.5),
    lowerIsBetter: true,
    status: "watch",
    read: (week) => `${formatWhole(week[week.length - 1] ?? 0)} open`,
  },
  {
    id: "reminders",
    label: "Reminders sent",
    icon: BellIcon,
    days: percent(421, 98.2, 98.6, 0.6),
    lowerIsBetter: false,
    status: "good",
    read: (week) => `${formatOnePlace(mean(week))}%`,
  },
  {
    id: "online",
    label: "Booked online",
    icon: GlobeIcon,
    days: percent(431, 54, 63, 4),
    lowerIsBetter: false,
    status: "good",
    read: (week) => `${formatOnePlace(mean(week))}%`,
  },
];

/** One signal over a range: the days to draw, the headline value and the percent change across the range. */
export function readSignal(signal: HealthSignal, range: HealthRange) {
  const days = signal.days.slice(-Number(range));
  const newest = days.slice(-7);
  return { days, value: signal.read(newest), change: percentChange(mean(days.slice(0, 7)), mean(newest)) };
}

const fall = (id: string) => {
  const signal = SIGNALS.find((item) => item.id === id);
  return signal ? formatOnePlace(Math.abs(readSignal(signal, "90").change)) : "0.0";
};
const newestWeek = (id: string) => SIGNALS.find((item) => item.id === id)?.days.slice(-7) ?? [];
const supportNow = formatWhole(newestWeek("support")[6] ?? 0);
const onlineNow = formatOnePlace(mean(newestWeek("online")));
const needAttention = SIGNALS.filter((signal) => signal.status !== "good").length;

/**
 * Sample summaries, standing in for text a model would write. Each one is two
 * short sentences built from the signal figures above, so it never disagrees
 * with the card.
 */
export const RISK_SUMMARIES: string[] = [
  `Bookings fell ${fall("bookings")}% in 90 days and fewer staff sign in. Patients still book online.`,
  `Staff sign-ins are down ${fall("staff")}% and ${supportNow} support requests are open. Reminders still arrive.`,
  `${needAttention} of ${SIGNALS.length} signals need attention. ${onlineNow}% of bookings are made online.`,
];

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

