const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

import { useState } from "react";

import { CheckIcon, PlusIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** Props for the recommended next step. */
export interface NextStepProps {
  /** What to do, in one line of at most 12 words. */
  action: string;
  className?: string;
}

/**
 * The one step the card recommends, with the one primary button. The button
 * stays in place and says what it did, so a person can take the step back.
 */
export function NextStep({ action, className }: NextStepProps) {
  const [added, setAdded] = useState(false);
  const Icon = added ? CheckIcon : PlusIcon;

  return (
    <div className={cn("flex flex-col items-start gap-3", className)}>
      <h3 className="sr-only">Next step</h3>
      <p className="text-sm leading-6 font-medium text-pretty @2xl:min-h-18">{action}</p>
      <Button
        variant={added ? "outline" : "default"}
        size="sm"
        aria-pressed={added}
        onClick={() => setAdded((current) => !current)}
        className="min-h-11 sm:min-h-8"
      >
        <Icon aria-hidden="true" className="size-4" />
        {added ? "Added to my tasks" : "Add to my tasks"}
      </Button>
    </div>
  );
}

import { cn } from "@/lib/utils";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the renewal term. */
export interface RenewalTermProps {
  /** The renewal day, written short, such as "Dec 12". */
  renews: string;
  totalDays: number;
  daysUsed: number;
  daysLeft: number;
  className?: string;
}

/**
 * When the account renews, in one quiet line, over a bar that shows how far
 * through the term it is. The bar only repeats the line, with a marker at today.
 */
export function RenewalTerm({ renews, totalDays, daysUsed, daysLeft, className }: RenewalTermProps) {
  const used = totalDays === 0 ? 0 : Math.min(100, (daysUsed / totalDays) * 100);
  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <p className="truncate text-sm text-muted-foreground tabular-nums">
        Renews {renews}, {daysLeft} {daysLeft === 1 ? "day" : "days"} left
      </p>
      <div aria-hidden="true" className="relative h-2 rounded-full bg-muted">
        <span className="w-(--w) absolute inset-y-0 left-0 rounded-full bg-primary" style={
          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
          { "--w": `${used}%` } as VarStyle
        } />
        <span className="left-(--x) absolute -inset-y-1 w-0.5 -translate-x-1/2 rounded-full bg-foreground ring-2 ring-card" style={
          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
          { "--x": `${used}%` } as VarStyle
        } />
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState } from "react";

import { RefreshIcon, SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** Props for the written risk summary. */
export interface RiskSummaryProps {
  /** The versions "Write again" steps through. They are sample text, so the block never calls a model. */
  versions: string[];
  className?: string;
}

/**
 * A machine-written summary of the account, two short sentences long. An icon
 * with a spoken label marks it as generated. The text sits in a box of fixed
 * height, so another version moves nothing under it.
 */
export function RiskSummary({ versions, className }: RiskSummaryProps) {
  const [version, setVersion] = useState(0);
  const reduceMotion = useReducedMotion();

  return (
    <div className={cn("flex flex-col items-start gap-3", className)}>
      <h3 className="sr-only">Summary</h3>
      <div className="flex gap-2">
        {/* A box one text line tall centres the icon on the first line, with no nudge. */}
        <span className="flex h-5 shrink-0 items-center">
          <SparklesIcon
            role="img"
            aria-label="Generated text"
            className="size-4 shrink-0 text-muted-foreground"
          />
        </span>
        <div aria-live="polite" className="min-h-18">
          <AnimatePresence initial={false} mode="wait">
            <motion.p
              key={version}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: reduceMotion ? 0 : 0.12 }}
              className="max-w-prose text-sm leading-6 text-pretty"
            >
              {versions[version]}
            </motion.p>
          </AnimatePresence>
        </div>
      </div>
      <Button
        variant="outline"
        size="sm"
        onClick={() => setVersion((current) => (current + 1) % versions.length)}
        className="min-h-11 sm:min-h-8"
      >
        <RefreshIcon aria-hidden="true" className="size-4" />
        Write again
      </Button>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

import { ROLL_WHOLE } from "../../lib/roll-formats";
import { type Status, STATUS_TEXT, STATUS_WORD } from "../../lib/status";

/** Props for the health score. */
export interface ScoreLeadProps {
  /** The score, from 0 to 100. */
  score: number;
  status: Status;
  /** How many points the score moved across the range. Read to screen readers only. */
  change: number;
  /** The words after the change, such as "in 30 days". */
  changeNote: string;
  className?: string;
}

/**
 * The health score as the one large figure of the card, with its state as a
 * mark and a word beside it. Nothing counts up on arrival: the digits roll
 * only when the score itself changes.
 */
export function ScoreLead({ score, status, change, changeNote, className }: ScoreLeadProps) {
  const points = Math.abs(change);
  const moved = change === 0 ? "No change" : `${change > 0 ? "Up" : "Down"} ${points} ${points === 1 ? "point" : "points"}`;

  return (
    <div className={cn("flex flex-col gap-1", className)}>
      <p className="text-5xl font-semibold tracking-tight whitespace-nowrap">
        <span className="sr-only">Health score </span>
        <NumberTicker value={score} format={ROLL_WHOLE} />{" "}
        <span className="text-sm font-normal tracking-normal text-muted-foreground">of 100</span>
      </p>
      <p className="flex items-center gap-1.5 text-sm font-medium whitespace-nowrap">
        <span aria-hidden="true" className={cn("size-2 rounded-full bg-current", STATUS_TEXT[status])} />
        {STATUS_WORD[status]}
        <span className="sr-only">
          . {moved} {changeNote}.
        </span>
      </p>
    </div>
  );
}

// NumberTicker memoises its formatter on the options object, so every block
// passes one of these constants and never an inline object.

/** A whole number with thousands separators, for a rolling figure. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/** A number with one decimal place, for a rolling figure. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

/** A dollar amount with no cents, for a rolling figure. */
export const ROLL_MONEY: Intl.NumberFormatOptions = { style: "currency", currency: "USD", maximumFractionDigits: 0 };

import { ArrowDownIcon, ArrowUpIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { formatPercent } from "../../lib/format";
import { STATUS_TEXT, STATUS_WORD } from "../../lib/status";
import { Sparkline } from "../../parts/sparkline";
import type { HealthSignal } from "./data";

/** Props for one signal row. */
export interface SignalRowProps {
  signal: HealthSignal;
  /** The days to draw in the sparkline. */
  days: number[];
  /** The headline value, already written out. */
  value: string;
  /** The percent change across the range. */
  change: number;
}

/**
 * One signal of the health score on one line: icon, name, value, trend and
 * state. Every column has a fixed width, so the rows line up and a longer
 * figure moves nothing. The state is a mark with its word, never colour alone.
 */
export function SignalRow({ signal, days, value, change }: SignalRowProps) {
  const Icon = signal.icon;
  const flat = Math.abs(change) < 0.05;
  const Arrow = change > 0 ? ArrowUpIcon : ArrowDownIcon;

  return (
    <li className="grid min-h-11 grid-cols-[1rem_1fr_5rem_4rem] items-center gap-x-3 px-5 py-2 @md:grid-cols-[1rem_1fr_5rem_4rem_4rem] @2xl:grid-cols-[1rem_1fr_5rem_5rem_4rem_4rem]">
      <Icon aria-hidden="true" className="size-4 text-muted-foreground" />
      <span className="truncate text-sm font-medium">{signal.label}</span>
      <span className="text-right text-sm whitespace-nowrap tabular-nums">{value}</span>
      <Sparkline values={days} className="hidden h-6 w-full @md:block" />
      <span className="hidden items-center justify-end gap-0.5 text-xs whitespace-nowrap text-muted-foreground tabular-nums @2xl:flex">
        {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
        <span className="sr-only">{flat ? "No change" : change > 0 ? "Up" : "Down"}</span>
        {formatPercent(change)}
      </span>
      <span className="flex items-center gap-1.5 text-sm font-medium whitespace-nowrap">
        <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full bg-current", STATUS_TEXT[signal.status])} />
        {STATUS_WORD[signal.status]}
      </span>
    </li>
  );
}

import { cn } from "@/lib/utils";

import { linePath, paddedExtent } from "../lib/plot";

/** Props for a sparkline. */
export interface SparklineProps {
  values: number[];
  className?: string;
}

/** A small trend line with no axis. Decorative: the figure beside it carries the number. */
export function Sparkline({ values, className }: SparklineProps) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
      className={cn("h-8 w-20 overflow-visible text-muted-foreground", className)}
    >
      <path
        d={linePath(values, paddedExtent([values], 0.15), 30)}
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}
